#!/usr/bin/env bash
LOG_FILE="__LOG_FILE__"
EXIT_CODE="__EXIT_CODE__"

echo "$@" >> "$LOG_FILE"

if [ "$#" -lt 2 ]; then
  exit "$EXIT_CODE"
fi

POSITIONS=()
while [ "$#" -gt 0 ]; do
  CURRENT="$1"
  shift
  if [ "${CURRENT#-}" != "$CURRENT" ]; then
    continue
  fi
  POSITIONS+=("$CURRENT")
done

LAST="${POSITIONS[${#POSITIONS[@]}-1]}"
FIRST_INPUT=""
for PATH_ARG in "${POSITIONS[@]}"; do
  if [ -f "$PATH_ARG" ]; then
    FIRST_INPUT="$PATH_ARG"
    break
  fi
done

if [ -n "$LAST" ]; then
  OUT_EXT="${LAST##*.}"
  OUT_EXT="${OUT_EXT,,}"
  if [ "$OUT_EXT" = "jpg" ] || [ "$OUT_EXT" = "jpeg" ]; then
    cat <<'JPEG' | base64 -d > "$LAST"

JPEG
  elif [ "$OUT_EXT" = "tif" ] || [ "$OUT_EXT" = "tiff" ]; then
    cat <<'TIFF' | base64 -d > "$LAST"
SUkqAAgAAAAKAAABBAABAAAAAQAAAAEBBAABAAAAAQAAAAIBAwADAAAAhgAAAAMBAwABAAAAAQAAAAYBAwABAAAAAgAAABEBBAABAAAAjAAAABUBAwABAAAAAwAAABYBBAABAAAAAQAAABcBBAABAAAAAwAAABwBAwABAAAAAQAAAAAAAAAIAAgACAD///8=
TIFF
  elif [ -n "$FIRST_INPUT" ] && [ "$FIRST_INPUT" != "$LAST" ]; then
    cp "$FIRST_INPUT" "$LAST"
  else
    touch "$LAST"
  fi
fi

exit "$EXIT_CODE"
